public class Solution {
    public ListNode MergeKLists(ListNode[] lists) {
        var queue = new PriorityQueue<ListNode, int>();
        foreach (var node in lists) {
            if (node != null) {
                queue.Enqueue(node, node.val);
            }
        }

        var dummy = new ListNode(0);
        var current = dummy;
        while (queue.Count > 0) {
            var node = queue.Dequeue();
            current.next = node;
            current = current.next;
            if (node.next != null) {
                queue.Enqueue(node.next, node.next.val);
            }
        }
        return dummy.next;
    }
}

public class Solution {
    public int Trap(int[] height) {
        int left = 0, right = height.Length - 1;
        int leftMax = 0, rightMax = 0;
        int water = 0;
        while (left < right) {
            if (height[left] <= height[right]) {
                leftMax = Math.Max(leftMax, height[left]);
                water += leftMax - height[left];
                left++;
            } else {
                rightMax = Math.Max(rightMax, height[right]);
                water += rightMax - height[right];
                right--;
            }
        }
        return water;
    }
}

public class Solution {
    public IList<IList<string>> SolveNQueens(int n) {
        var results = new List<IList<string>>();
        var columns = new HashSet<int>();
        var diagonals = new HashSet<int>();
        var antiDiagonals = new HashSet<int>();
        var board = new int[n];

        void Backtrack(int row) {
            if (row == n) {
                var solution = new List<string>();
                for (int r = 0; r < n; r++) {
                    var rowChars = new char[n];
                    Array.Fill(rowChars, '.');
                    rowChars[board[r]] = 'Q';
                    solution.Add(new string(rowChars));
                }
                results.Add(solution);
                return;
            }
            for (int col = 0; col < n; col++) {
                int diag = row - col;
                int antiDiag = row + col;
                if (columns.Contains(col) || diagonals.Contains(diag) || antiDiagonals.Contains(antiDiag)) {
                    continue;
                }
                columns.Add(col);
                diagonals.Add(diag);
                antiDiagonals.Add(antiDiag);
                board[row] = col;

                Backtrack(row + 1);

                columns.Remove(col);
                diagonals.Remove(diag);
                antiDiagonals.Remove(antiDiag);
            }
        }

        Backtrack(0);
        return results;
    }
}
